from itertools import product

# Partitions are decreasing tuples of positive integers; () is empty.
def contained(lam, mu):
    n = max(len(lam), len(mu))
    return all((lam[k] if k < len(lam) else 0) <= (mu[k] if k < len(mu) else 0)
               for k in range(n))

def partitions_of(n, max_part=None):
    if n == 0:
        yield ()
        return
    if max_part is None or max_part > n:
        max_part = n
    for first in range(max_part, 0, -1):
        for tail in partitions_of(n-first, first):
            yield (first,) + tail

def in_box(mu, q, r):
    return len(mu) <= r and (not mu or mu[0] <= q)

def horizontal_strip(lam, mu):
    if not contained(lam, mu):
        return False
    width = max(lam[0] if lam else 0, mu[0] if mu else 0)
    return all(sum(x >= col for x in mu) - sum(x >= col for x in lam) in (0, 1)
               for col in range(1, width + 1))

def pieri(lam, k, q, r):
    return {mu for mu in partitions_of(sum(lam)+k)
            if in_box(mu, q, r) and horizontal_strip(lam, mu)}

def slots(i, j, p, c):
    return {
        'x0': (i,)*j,
        'x1': (i+1,) + (i,)*(j-1),
        'y1': (i,)*j + (1,),
        'gamma': (i+2,) + (i,)*(j-1) if p >= 2 else None,
        'x2': (i+1, i+1) + (i,)*(j-2),
        'z': (i+1,) + (i,)*(j-1) + (1,),
        'y2': (i,)*j + (2,),
        'theta': (i,)*j + (1, 1) if c >= 2 else None,
    }

def present(*parts):
    return {part for part in parts if part is not None}

parameter_tuples = identity_checks = double_boundary_checks = 0
for i, j in product(range(2, 7), repeat=2):
    for p, c in product(range(1, 6), repeat=2):
        if min(p, c) != 1:
            continue
        S = slots(i, j, p, c)
        q, r = i+p, j+c
        tests = (
            ('h1*x0', pieri(S['x0'], 1, q, r), present(S['x1'], S['y1'])),
            ('h2*x0', pieri(S['x0'], 2, q, r), present(S['gamma'], S['z'], S['y2'])),
            ('h1*x1', pieri(S['x1'], 1, q, r), present(S['gamma'], S['x2'], S['z'])),
            ('h1*y1', pieri(S['y1'], 1, q, r), present(S['z'], S['y2'], S['theta'])),
        )
        for name, actual, expected in tests:
            assert actual == expected, (i, j, p, c, name, actual, expected)
            identity_checks += 1
        if p == c == 1:
            columns = ['x2', 'z', 'y2']
            rows = [[int(S[name] in pieri(lam, k, q, r)) for name in columns]
                    for lam, k in ((S['x0'], 2), (S['x1'], 1), (S['y1'], 1))]
            assert rows == [[0, 1, 1], [1, 1, 0], [0, 1, 1]], rows
            # Rows 1,2 and columns (z,y2), with one-based row notation.
            minor = [[rows[a][b] for b in (1, 2)] for a in (0, 1)]
            det = minor[0][0]*minor[1][1] - minor[0][1]*minor[1][0]
            assert minor == [[1, 1], [1, 0]] and det == -1, (minor, det)
            double_boundary_checks += 1
        parameter_tuples += 1

print('INPUT_I_J: 2..6')
print('INPUT_P_C: 1..5 with min(p,c)=1')
print('PARAMETER_TUPLES:', parameter_tuples)
print('PIERI_IDENTITIES_CHECKED:', identity_checks)
print('DOUBLY_BOUNDARY_MATRIX_CHECKS:', double_boundary_checks)
print('DOUBLY_BOUNDARY_MATRIX_COLUMNS: [x2,z,y2]')
print('DOUBLY_BOUNDARY_MATRIX: [[0,1,1],[1,1,0],[0,1,1]]')
print('DOUBLY_BOUNDARY_MINOR_ROWS_ONE_BASED: [1,2]')
print('DOUBLY_BOUNDARY_MINOR_COLUMNS: [z,y2]')
print('DOUBLY_BOUNDARY_MINOR: [[1,1],[1,0]]')
print('DOUBLY_BOUNDARY_MINOR_DETERMINANT: -1')
print('RESULT: PASS')
